// Translated static segments: their message ids and text, the catalogs Angular's build inlines,
// and the per-locale tree check. Generated bytes never depend on a catalog; catalogs only decide
// whether a locale's translated tree is valid.
import { readFile } from "node:fs/promises";
import { isStaticSegment, type Segment } from "../../_core/src/path.js";
import { selections } from "./validate.js";
import type { Declaration, Sources } from "./sources.js";

/** The build's i18n configuration, as Angular's application builder reads it. */
export interface Localization {
  sourceLocale: string;
  // Absolute paths, in merge order: a later file wins on a duplicate id.
  locales: readonly { code: string; files: readonly string[] }[];
  polyfills: readonly string[];
}

const meaning = "URL path segment";
const description =
  'One segment of page URLs, without "/". Changing it changes links and bookmarks.';
const init = "@angular/localize/init";

/** One message per distinct canonical word, so a word is translated once and ids survive moves. */
export function segmentId(text: string): string {
  return `route.segment.${encodeURIComponent(text)}`;
}

/** The `$localize` tagged template a destination copy writes for one static segment. */
export function segmentMessage(text: string): string {
  // A static segment never starts with ":", so its text needs no leading "\:" after the block.
  // Line terminators are escaped: a template normalizes a literal CR or CRLF to LF, and the
  // message must stay on the declaration's line for copy diagnostics.
  const escaped = text
    .replace(/[\\`]/g, "\\$&")
    .replace(/\$\{/g, "\\${")
    .replace(/\r/g, "\\r")
    .replace(/\n/g, "\\n")
    .replace(/\u2028/g, "\\u2028")
    .replace(/\u2029/g, "\\u2029");

  return `$localize\`:${meaning}|${description}@@${segmentId(text)}:${escaped}\``;
}

// The structural slice of @angular/localize/tools this file reads; its own types stay out of the
// emitted declarations, since @angular/localize is an optional peer.
interface Translation {
  readonly messageParts: readonly string[];
  readonly placeholderNames: readonly string[];
}

interface Parser {
  analyze(path: string, contents: string): { canParse: boolean; hint: unknown };
  parse(
    path: string,
    contents: string,
    hint: unknown,
  ): { locale?: string; translations: Record<string, Translation> };
}

interface Tools {
  readonly ArbTranslationParser: new () => Parser;
  readonly SimpleJsonTranslationParser: new () => Parser;
  readonly Xliff1TranslationParser: new () => Parser;
  readonly Xliff2TranslationParser: new () => Parser;
  readonly XtbTranslationParser: new () => Parser;
}

/** A translation and the catalog file it came from. */
export interface CatalogEntry {
  readonly translation: Translation;
  readonly file: string;
}

/** Angular's parsers, in the order its translation loader tries them. */
async function parsers(): Promise<readonly (readonly [string, Parser])[]> {
  // A specifier TypeScript doesn't resolve: the optional peer's types stay out of every program
  // that compiles this file (Launch's included), and the import stays a runtime-only dependency.
  const specifier: string = "@angular/localize/tools";
  let tools: Tools;

  try {
    tools = (await import(specifier)) as Tools;
  } catch {
    throw new Error("translateSegments needs @angular/localize: run ng add @angular/localize");
  }

  return [
    ["arb", new tools.ArbTranslationParser()],
    ["json", new tools.SimpleJsonTranslationParser()],
    ["xlf", new tools.Xliff1TranslationParser()],
    ["xlf2", new tools.Xliff2TranslationParser()],
    ["xmb", new tools.XtbTranslationParser()],
  ];
}

/**
 * Every locale's merged catalog, loaded as Angular's builder loads it: the first parser whose
 * analysis accepts a file parses it, a later file wins on a duplicate id, and the diagnostics a
 * parser returns are ignored, as Angular's loader ignores them. A file no parser accepts, or a
 * parser that throws, fails.
 */
export async function loadCatalogs(
  localization: Localization,
): Promise<Map<string, { format: string[]; entries: Map<string, CatalogEntry> }>> {
  const list = await parsers();
  const result = new Map<string, { format: string[]; entries: Map<string, CatalogEntry> }>();

  for (const locale of localization.locales) {
    const format: string[] = [];
    const entries = new Map<string, CatalogEntry>();

    for (const file of locale.files) {
      let contents: string;

      try {
        contents = await readFile(file, "utf8");
      } catch (error) {
        throw new Error(`Locale ${locale.code}: can't read translation file ${file}`, {
          cause: error,
        });
      }

      let parsed: ReturnType<Parser["parse"]> | undefined;

      for (const [name, parser] of list) {
        const analysis = parser.analyze(file, contents);

        if (!analysis.canParse) {
          continue;
        }

        try {
          parsed = parser.parse(file, contents, analysis.hint);
        } catch (error) {
          throw new Error(`Locale ${locale.code}: can't parse translation file ${file}`, {
            cause: error,
          });
        }

        format.push(name);

        break;
      }

      if (!parsed) {
        throw new Error(
          `Locale ${locale.code}: unsupported translation file format in ${file}; Angular reads ARB, JSON, XLIFF 1.2, XLIFF 2 and XTB`,
        );
      }

      for (const [id, translation] of Object.entries(parsed.translations)) {
        entries.set(id, { translation, file });
      }
    }

    result.set(locale.code, { format, entries });
  }

  return result;
}

// Why `text` can't be a translated segment, or undefined when it can.
function invalidity(text: string): string | undefined {
  if (isStaticSegment(text)) {
    return undefined;
  }

  if (text === "") {
    return "a route segment can't be empty";
  }

  if (text.includes("/")) {
    return 'a route segment can\'t contain "/"';
  }

  if (text.startsWith("$") || text.startsWith(":")) {
    return 'a route segment can\'t start with "$" or ":"';
  }

  if (!text.isWellFormed()) {
    return "a route segment's Unicode must be well formed";
  }

  return 'a route segment can\'t be ".", "..", "*" or "**"';
}

// The tree Angular's inliner builds for one locale: every declaration copied with its static
// words mapped, parent, children and target rewired, id and source kept. Copies, since
// selections() sets `full` on what it reads.
function translatedView(sources: Sources, text: (word: string) => string): Sources {
  function map(segments: readonly Segment[]): readonly Segment[] {
    const result: Segment[] = [];

    for (const segment of segments) {
      if (segment.kind === "static") {
        result.push({ kind: "static", text: text(segment.text) });
      } else {
        result.push(segment);
      }
    }

    return result;
  }

  function authored(segments: readonly Segment[]): string {
    const parts: string[] = [];

    for (const segment of segments) {
      if (segment.kind === "static") {
        parts.push(segment.text);
      } else if (segment.kind === "catchall") {
        parts.push(`$${segment.name}[]`);
      } else {
        parts.push(`$${segment.name}`);
      }
    }

    return parts.join("/");
  }

  const copies = new Map<Declaration, Declaration>();

  for (const declaration of sources.declarations) {
    const segments = map(declaration.segments);
    let branch = declaration.branch;

    // The anchor holds source words, like `effective`; the outlet name is never translated.
    if (branch) {
      branch = { outlet: branch.outlet, anchor: map(branch.anchor) };
    }

    copies.set(declaration, {
      ...declaration,
      path: authored(segments),
      segments,
      effective: map(declaration.effective),
      branch,
      children: [],
    });
  }

  for (const [declaration, copy] of copies) {
    if (declaration.parent) {
      copy.parent = copies.get(declaration.parent);
    }

    if (declaration.target) {
      copy.target = copies.get(declaration.target);
    }

    for (const child of declaration.children) {
      copy.children.push(copies.get(child)!);
    }
  }

  return { ...sources, declarations: [...copies.values()] };
}

/**
 * Checks every configured locale's translated tree before any write: each translation of a route
 * word must be one valid static segment without placeholders, and the tree must pass the same
 * collision and overlap rules as the canonical one. A word a catalog doesn't translate stands as
 * its source text, as Angular's inliner ships it; completeness is Angular's to enforce.
 */
export async function validateLocales(sources: Sources, localization: Localization): Promise<void> {
  if (!localization.polyfills.includes(init)) {
    throw new Error(
      `translateSegments needs the ${init} polyfill: add it to the build's polyfills (ng add @angular/localize does)`,
    );
  }

  const catalogs = await loadCatalogs(localization);
  const words = new Set<string>();

  for (const declaration of sources.declarations) {
    for (const segment of declaration.segments) {
      if (segment.kind === "static") {
        words.add(segment.text);
      }
    }
  }

  // The source locale's text is the canonical text, which the canonical check already covered.
  for (const locale of localization.locales) {
    const { entries } = catalogs.get(locale.code)!;
    const translated = new Map<string, string>();

    for (const word of words) {
      const id = segmentId(word);
      const entry = entries.get(id);

      if (!entry) {
        translated.set(word, word);

        continue;
      }

      const { messageParts, placeholderNames } = entry.translation;
      const text = messageParts.join("");

      if (placeholderNames.length > 0) {
        throw new Error(
          `Locale ${locale.code}: ${id} translates to ${JSON.stringify(text)} (${entry.file}): a route segment can't hold placeholders`,
        );
      }

      const reason = invalidity(text);

      if (reason) {
        throw new Error(
          `Locale ${locale.code}: ${id} translates to ${JSON.stringify(text)} (${entry.file}): ${reason}`,
        );
      }

      translated.set(word, text);
    }

    try {
      selections(translatedView(sources, (word) => translated.get(word)!));
    } catch (error) {
      if (error instanceof Error) {
        throw new Error(`Locale ${locale.code}: ${error.message}`, { cause: error });
      }

      throw error;
    }
  }
}
